ALTER TABLE public.recipes ALTER COLUMN author_id DROP NOT NULL;

INSERT INTO public.recipes (title, description, ingredients, steps, prep_time_minutes, categories, image_url) VALUES
('ხაჭაპური აჭარული', 'ოქროსფერი, ნავივით ნამცხვარი დნობადი სულგუნით და თბილი კვერცხის გულით — შავი ზღვის სანაპიროს კლასიკა.',
 '["ფქვილი 500 გრ","ცომის საფუარი 10 გრ","თბილი წყალი 250 მლ","შაქარი 1 კოვზი","მარილი 1 კოვზი","სულგუნი 400 გრ","იმერული ყველი 200 გრ","კვერცხი 3 ცალი","კარაქი 50 გრ"]'::jsonb,
 '["წყალში გახსენით საფუარი, შაქარი და მარილი; დაუმატეთ ფქვილი და მოზილეთ რბილი ცომი.","დააფარეთ და დატოვეთ თბილ ადგილას 1 საათი, სანამ არ გაორმაგდება.","ცომი ორად გაყავით, გახეხეთ და მიეცით ნავის ფორმა კიდეების დაგრეხით.","შუაში ჩაყარეთ დამუშავებული სულგუნისა და იმერულის ნაზავი.","გამოაცხვეთ 220 გრადუსზე 12-15 წუთი.","ცხელს გატეხეთ კვერცხი შუაში, ზემოდან დაადეთ კარაქი და კიდევ 2 წუთი გაუჩერეთ ღუმელში."]'::jsonb,
 90, ARRAY['breakfast','lunch'], 'https://images.unsplash.com/photo-1600891964092-4316c288032e?w=1200&q=80'),
('ხინკალი კალმახით', 'თხელი ცომში გახვეული წვნიანი ხორცი — ქართული სუფრის სიმბოლო, რომელიც ხელით უნდა შეჭამო.',
 '["ფქვილი 500 გრ","წყალი 220 მლ","მარილი 1 კოვზი","საქონლის ხორცი დაფქვილი 400 გრ","ღორის ხორცი დაფქვილი 200 გრ","ხახვი 2 ცალი","ქინძი 1 კონა","ომბალო 1 ჩ.კ.","შავი წიწაკა 1 ჩ.კ.","ცივი წყალი 100 მლ"]'::jsonb,
 '["ფქვილს დაუმატეთ წყალი და მარილი, მოზილეთ მაგარი ცომი. დატოვეთ 30 წუთი.","ხახვი და ქინძი წვრილად დაჭერით და აურიეთ ორ ხორცში.","დაუმატეთ სანელებლები და ცივი წყალი.","ცომი დაჭერით 5 სმ დისკებად, გახეხეთ და ცენტრში ჩადეთ ხორცი.","აკეცეთ 19-24 ნაკეცად, თავზე მკვრივი კუდი გაუკეთეთ.","ჩააგდეთ მოხარშულ, დამარილებულ წყალში და მოხარშეთ 7-8 წუთი."]'::jsonb,
 75, ARRAY['lunch','dinner'], 'https://images.unsplash.com/photo-1625944525533-473f1a3d54e7?w=1200&q=80'),
('ჩახოხბილი ქათმით', 'ხახვისა და პომიდვრის საწებელში ნელ ცეცხლზე მოხარშული ქათამი, ქართული სანელებლების თბილი სურნელით.',
 '["ქათმის ბარკლები 1 კგ","ხახვი 4 ცალი","პომიდორი 500 გრ","ნიორი 4 კბილი","ქინძი 1 კონა","ომბალო 1 ჩ.კ.","უცხო სუნელი 1 ჩ.კ.","მარილი და წიწაკა გემოვნებით"]'::jsonb,
 '["ქათმის ნაჭრები შეწვით ცხელ ტაფაზე ზეთის გარეშე, სანამ ცხიმი არ გამოვა.","დაუმატეთ წვრილად დაჭრილი ხახვი და მოშუშეთ 15 წუთი.","ჩააგდეთ გახეხილი პომიდვრები, დახურეთ სახურავი და შუშეთ 25 წუთი.","დაუმატეთ ნიორი, ქინძი და სუნელები.","შუშეთ კიდევ 5-7 წუთი და მიირთვით მჭადთან ერთად."]'::jsonb,
 60, ARRAY['dinner','lunch'], 'https://images.unsplash.com/photo-1604908176997-125f25cc6f3d?w=1200&q=80'),
('ფხალი ისპანახით', 'ცივი, ნიგოზიანი წამოსაწყისი — მწვანილის სიხალისე და ნიგოზის მიწიერი გემო ერთ ლუკმაში.',
 '["ისპანახი 500 გრ","ნიგოზი 200 გრ","ნიორი 3 კბილი","ხახვი წითელი 1 ცალი","ღვინის ძმარი 2 კოვზი","უცხო სუნელი 1 ჩ.კ.","ქინძი, ოხრახუში 1 კონა","ბროწეულის მარცვლები დასამშვენებლად","მარილი გემოვნებით"]'::jsonb,
 '["ისპანახი მოხარშეთ 3 წუთი, გაწურეთ და კარგად გამოწურეთ.","ნიგოზი, ნიორი და მწვანილი ერთად დაფქვით.","აურიეთ დაჭრილ ისპანახს, დაუმატეთ ძმარი, სუნელი და მარილი.","ჩამოაყალიბეთ პატარა ბურთულებად და დაამშვენეთ ბროწეულით."]'::jsonb,
 30, ARRAY['lunch','dinner'], 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?w=1200&q=80'),
('ლობიო ქოთანში', 'წითელი ლობიო თიხის ქოთანში, ქინძით და მჭადით — ზამთრის საუკეთესო კომფორტი.',
 '["წითელი ლობიო 400 გრ","ხახვი 2 ცალი","ნიორი 4 კბილი","ქინძი 1 კონა","უცხო სუნელი 1 კოვზი","ომბალო 1 ჩ.კ.","წითელი წიწაკა ნახევარი ჩ.კ.","მარილი გემოვნებით"]'::jsonb,
 '["ლობიო წინა ღამით დაასველეთ.","მოხარშეთ ნელ ცეცხლზე 1.5 საათი სანამ არ დარბილდება.","ცალკე ტაფაზე მოშუშეთ ხახვი; დაუმატეთ ლობიოს.","დაუმატეთ დანაყილი ნიორი, ქინძი და სუნელები.","მიირთვით ცხელ მჭადთან და მწნილთან ერთად."]'::jsonb,
 105, ARRAY['lunch','dinner'], 'https://images.unsplash.com/photo-1547592180-85f173990554?w=1200&q=80'),
('ბადრიჯანი ნიგვზით', 'თხელი ბადრიჯნის ფურცლებში გახვეული ცხარე ნიგოზი — ქართული სუფრის ცნობილი გემო.',
 '["ბადრიჯანი 4 ცალი","ნიგოზი 200 გრ","ნიორი 4 კბილი","ძმარი 1 კოვზი","უცხო სუნელი 1 ჩ.კ.","ცხარე წიწაკა ნახევარი ჩ.კ.","ბროწეული დასამშვენებლად","ზეთი შესაწვავად","მარილი გემოვნებით"]'::jsonb,
 '["ბადრიჯანი დაჭერით სიგრძეზე ფურცლებად და დაასველეთ დამარილებულ წყალში 20 წუთი.","შეწვით ცხელ ზეთში ორივე მხრიდან ოქროსფრად.","ნიგოზი, ნიორი, ძმარი და სუნელები კარგად აურიეთ.","ცოტა ცომი დაუსვით ბადრიჯანის ფურცელს და გახვიეთ რულეტად.","დაამშვენეთ ბროწეულის მარცვლებით."]'::jsonb,
 45, ARRAY['lunch','dinner'], 'https://images.unsplash.com/photo-1541519227354-08fa5d50c44d?w=1200&q=80'),
('ჩურჩხელა ნიგვზით', 'ტკბილი ღვინის სიროფში ჩამოწებული ნიგოზი — ქართული ტკბილი სოსისი საუკუნეების მანძილზე.',
 '["ყურძნის ტკბილი 1 ლ","ფქვილი 100 გრ","ნიგოზი 300 გრ ცალი-ცალი","ბამბის ძაფი"]'::jsonb,
 '["ნიგოზი ცალ-ცალი ჩააგრეთ ძაფზე 25 სმ სიგრძეზე.","ტკბილი ცეცხლზე ცხლდი და თანდათან უმატეთ ფქვილს, გამუდმებით მოურიეთ სანამ არ გახდება პელამუშივით სქელი.","თითოეული ნიგოზის ძაფი ჩააგდეთ ცხელ ტკბილში, ამოიღეთ და ჩამოკიდეთ ბუნებრივ პირობებში.","გააგრილეთ და გააშრეთ სულ მცირე 1 კვირა."]'::jsonb,
 180, ARRAY['dessert'], 'https://images.unsplash.com/photo-1607478900766-efe13248b125?w=1200&q=80'),
('ფელამუში ყურძნის', 'ცივი, გლუვი ტკბილეული ყურძნის ტკბილისგან — შემოდგომის ტრადიცია.',
 '["ყურძნის ტკბილი 1 ლ","ფქვილი სიმინდის 200 გრ","ნიგოზი 100 გრ დასაფქვევად","ბროწეული დასამშვენებლად"]'::jsonb,
 '["ცოტა ტკბილში გახსენით სიმინდის ფქვილი გაცივებულში სიმსივნის თავიდან ასაცილებლად.","დანარჩენი ტკბილი მოადუღეთ და თანდათან ჩაასხით ფქვილიანი ნაზავი.","მოხარშეთ 15 წუთი გამუდმებული მორევით.","ჩაასხით პატარა ფინჯნებში, გააცივეთ.","მიირთვით ნიგოზისა და ბროწეულის მარცვლების მოყრით."]'::jsonb,
 40, ARRAY['dessert'], 'https://images.unsplash.com/photo-1587049352846-4a222e784d38?w=1200&q=80'),
('ტკემალი მწვანე', 'მჟავე-ცხარე საწებელი მწვანე ტყემლისგან — ხორცის, კარტოფილისა და ხაჭაპურის საუკეთესო კომპანიონი.',
 '["მწვანე ტყემალი 1 კგ","ნიორი 6 კბილი","ქინძი 2 კონა","ომბალო 2 კონა","წიწაკა ცხარე 2 ცალი","წყალი 200 მლ","მარილი გემოვნებით"]'::jsonb,
 '["ტყემალი ჩააგდეთ წყალში, მოხარშეთ 15 წუთი და გაწურეთ ცხრილში.","მიღებული პიურე დააბრუნეთ ცეცხლზე.","დაუმატეთ დანაყილი ნიორი, მწვანილი და წიწაკა.","მოხარშეთ ნელ ცეცხლზე 20 წუთი, დაუმატეთ მარილი გემოვნებით.","ცხლად ჩაასხით სტერილურ ქილებში."]'::jsonb,
 50, ARRAY['lunch','dinner'], 'https://images.unsplash.com/photo-1466637574441-749b8f19452f?w=1200&q=80'),
('მაწონი ხილით', 'ცოცხალი ბაქტერიების მქონე ქართული იოგურტი, თაფლით, კაკლითა და სეზონური ხილით — მსუბუქი საუზმე.',
 '["მაწონი 500 გრ","თაფლი 3 კოვზი","ნიგოზი 60 გრ","ბროწეული 1 ცალი","ბანანი 1 ცალი","დარიჩინი გემოვნებით"]'::jsonb,
 '["მაწონი კარგად აურიეთ და ჩაასხით ღრმა თასში.","ზემოდან დაასხით თაფლი.","დაარჩექით ნიგოზი და მოაყარეთ.","დაამატეთ დაჭრილი ბანანი და ბროწეულის მარცვლები.","მოაყარეთ ცოტა დარიჩინი და მიირთვით მაშინვე."]'::jsonb,
 10, ARRAY['breakfast'], 'https://images.unsplash.com/photo-1488477181946-6428a0291777?w=1200&q=80'),
('ღვინო საფერავი', 'მუქი, სქელი წითელი ღვინო კახეთიდან — ხორცის კერძების იდეალური თანმხლები. მიაწოდეთ 16-18 გრადუსზე.',
 '["საფერავი 1 ბოთლი","ღვინის ჭიქები 4 ცალი"]'::jsonb,
 '["ბოთლი 1 საათით ადრე ამოიღეთ მაცივრიდან.","გახსენით და დატოვეთ 15 წუთი ჩასუნთქვისთვის.","ჩაასხით ჭიქებში დაახლოებით მესამედამდე.","მიაწოდეთ მწვადს, ჩაქაფულს ან ხახვიან ლობიოს გვერდით."]'::jsonb,
 15, ARRAY['drink'], 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=1200&q=80'),
('ტარხუნის ლიმონათი', 'ღია მწვანე, გამაგრილებელი გაზიანი სასმელი ტარხუნის თბილი, ანისისებრი გემოთი.',
 '["ტარხუნის ფოთლები 1 კონა","შაქარი 150 გრ","წყალი 250 მლ სიროპისთვის","ლიმონის წვენი 2 კოვზი","გაზიანი წყალი 1 ლ","ყინული"]'::jsonb,
 '["წყალში გახსენით შაქარი, გააცხელეთ სიროპამდე.","დაუმატეთ ტარხუნის ფოთლები, გამორთეთ ცეცხლი და დატოვეთ 30 წუთი.","გაწურეთ და დაუმატეთ ლიმონის წვენი.","ჭიქებში ჩაყარეთ ყინული, ჩაასხით 3 კოვზი სიროპი და ზემოდან შეავსეთ გაზიანი წყლით.","დაამშვენეთ ტარხუნის ფოთოლით."]'::jsonb,
 40, ARRAY['drink','dessert'], 'https://images.unsplash.com/photo-1621263764928-df1444c5e859?w=1200&q=80');